package vmcompat;
import java.nio.*;import org.lwjgl.*;import org.lwjgl.glfw.*;import org.lwjgl.opengl.*;
/** Lossless byte/float/depth and mip decoding through the production packer. */
public final class PackingFormatsTests {
 static void check(boolean b,String text){if(!b)throw new AssertionError(text+" / GL="+GL11.glGetError());}
 static void pixel(int p,float expected,float lod){GL20.glUniform1f(GL20.glGetUniformLocation(p,"level"),lod);Draws.glDrawArrays(GL11.GL_TRIANGLES,0,3);FloatBuffer b=BufferUtils.createFloatBuffer(4);GL11.glReadPixels(8,8,1,1,GL11.GL_RGBA,GL11.GL_FLOAT,b);check(Math.abs(b.get(0)-expected)<.00001,"float/mip pixel "+b.get(0)+" expected "+expected);check(GL11.glGetError()==0,"draw clean");}
 static void bind(int p,int texture){Samplers.glActiveTexture(GL13.GL_TEXTURE0);Samplers.glBindTexture(GL11.GL_TEXTURE_2D,texture);for(int i=0;i<16;i++)Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"images["+i+"]"),0);Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"a"),0);Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"b"),0);}
 public static void main(String[] a){check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);long w=Context.createWindow(16,16,"Packing value precision",0,0);Context.makeCurrent(w);Context.capabilities();GL11.glViewport(0,0,16,16);Draws.glBindVertexArray(GL30.glGenVertexArrays());int p=StorageBuffersTests.program("#version 330\nuniform sampler2D images[16];uniform sampler2D a;uniform sampler2D b;uniform float level;out vec4 c;void main(){float sum=0;for(int i=0;i<16;i++)sum+=textureLod(images[i],vec2(.5),level).r;c=vec4((sum+texture(a,vec2(.5)).r+texture(b,vec2(.5)).r)/18.,0,0,1);}");Shaders.glUseProgram(p);
  int fbo=GL30.glGenFramebuffers(),target=Textures.glCreateTextures(GL11.GL_TEXTURE_2D);Textures.glTextureStorage2D(target,1,GL30.GL_RGBA32F,16,16);GL30.glBindFramebuffer(GL30.GL_FRAMEBUFFER,fbo);Gl41.glFramebufferTexture2D(GL30.GL_FRAMEBUFFER,GL30.GL_COLOR_ATTACHMENT0,GL11.GL_TEXTURE_2D,target,0);check(GL30.glCheckFramebufferStatus(GL30.GL_FRAMEBUFFER)==GL30.GL_FRAMEBUFFER_COMPLETE,"FBO");
  int texture=Textures.glCreateTextures(GL11.GL_TEXTURE_2D);Textures.glTextureStorage2D(texture,2,GL11.GL_RGBA8,2,2);Textures.glTextureParameteri(texture,GL11.GL_TEXTURE_MIN_FILTER,GL11.GL_NEAREST_MIPMAP_NEAREST);Textures.glTextureParameteri(texture,GL11.GL_TEXTURE_MAG_FILTER,GL11.GL_NEAREST);ByteBuffer data=BufferUtils.createByteBuffer(16);for(int i=0;i<4;i++)data.put(new byte[]{64,0,0,(byte)255});data.flip();Textures.glTextureSubImage2D(texture,0,0,0,2,2,GL11.GL_RGBA,GL11.GL_UNSIGNED_BYTE,data);data.clear().limit(4).put(new byte[]{(byte)192,0,0,(byte)255}).flip();Textures.glTextureSubImage2D(texture,1,0,0,1,1,GL11.GL_RGBA,GL11.GL_UNSIGNED_BYTE,data);bind(p,texture);pixel(p,64/255f,0);pixel(p,(16*192+2*64)/(18*255f),1);Textures.glDeleteTextures(texture);
  for(int format:new int[]{GL30.GL_RGBA32F,GL30.GL_RGBA16F,GL30.GL_DEPTH_COMPONENT32F}){texture=Textures.glCreateTextures(GL11.GL_TEXTURE_2D);Textures.glTextureStorage2D(texture,1,format,1,1);Textures.glTextureParameteri(texture,GL11.GL_TEXTURE_MIN_FILTER,GL11.GL_NEAREST);Textures.glTextureParameteri(texture,GL11.GL_TEXTURE_MAG_FILTER,GL11.GL_NEAREST);boolean depth=format==GL30.GL_DEPTH_COMPONENT32F;float value=depth?.375f:format==GL30.GL_RGBA16F?.12347412109375f:1.234567f;ByteBuffer floats=BufferUtils.createByteBuffer(depth?4:16);floats.putFloat(value);if(!depth)floats.putFloat(0).putFloat(0).putFloat(1);floats.flip();Textures.glTextureSubImage2D(texture,0,0,0,1,1,depth?GL11.GL_DEPTH_COMPONENT:GL11.GL_RGBA,GL11.GL_FLOAT,floats);bind(p,texture);pixel(p,value,0);Textures.glDeleteTextures(texture);}
  Shaders.glDeleteProgram(p);Context.destroyWindow(w);GLFW.glfwTerminate();System.out.println("PASS RGBA8 mip selection, RGBA32F >1, RGBA16F and depth precision");
 }
}
